package com.gymflow.inventory;import com.gymflow.gym.*;import com.gymflow.product.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;import java.util.*;
@Service public class InventoryService{private final StockBalanceRepository balances;private final StockMovementRepository movements;private final ProductRepository products;private final GymRepository gyms;public InventoryService(StockBalanceRepository b,StockMovementRepository m,ProductRepository p,GymRepository g){balances=b;movements=m;products=p;gyms=g;}
 @Transactional public StockMovementResponse move(UUID gymId,StockMovementRequest r){Gym gym=gyms.findById(gymId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Gimnasio no encontrado."));Product product=products.findByIdAndGym_Id(r.productId(),gymId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Producto no encontrado en este gimnasio."));StockBalance balance=balances.findLocked(gymId,product.getId()).orElseGet(()->balances.saveAndFlush(new StockBalance(gym,product)));int delta=switch(r.type()){case IN,INITIAL->r.quantity();case OUT->-r.quantity();case ADJUSTMENT->throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Usa IN u OUT para registrar ajustes trazables.");};if(r.type()==MovementType.INITIAL&&balance.getQuantity()!=0)throw new ResponseStatusException(HttpStatus.CONFLICT,"El inventario inicial solo puede registrarse cuando el saldo es cero.");int newQty=balance.getQuantity()+delta;if(newQty<0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Stock insuficiente: el inventario no puede quedar negativo.");balance.setQuantity(newQty);return StockMovementResponse.from(movements.save(new StockMovement(gym,product,r.type(),r.quantity(),r.reason())));}
 @Transactional(readOnly=true)public List<StockBalanceResponse> balances(UUID gymId){if(!gyms.existsById(gymId))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Gimnasio no encontrado.");return balances.findAllByGym_IdOrderByProduct_Name(gymId).stream().map(StockBalanceResponse::from).toList();}
 @Transactional(readOnly=true)public List<StockMovementResponse> movements(UUID gymId){return movements.findAllByGym_IdOrderByCreatedAtDesc(gymId).stream().map(StockMovementResponse::from).toList();}}
